cypress_script:
describe('Customer Registration Form', () => {
  it('should successfully register a new user', () => {
    cy.visit('https://parabank.parasoft.com/parabank/register.htm');
    cy.get('input[name="customer.firstName"]').type('John');
    cy.get('input[name="customer.lastName"]').type('Doe');
    cy.get('input[name="customer.address.street"]').type('123 Main St');
    cy.get('input[name="customer.address.city"]').type('Anytown');
    cy.get('input[name="customer.address.state"]').type('CA');
    cy.get('input[name="customer.address.zipCode"]').type('90210');
    cy.get('input[name="customer.phoneNumber"]').type('5551234567');
    cy.get('input[name="customer.ssn"]').type('123-45-6789');
    cy.get('input[name="customer.username"]').type('johndoe');
    cy.get('input[name="customer.password"]').type('password123');
    cy.get('input[name="repeatedPassword"]').type('password123');
    cy.get('input[type="submit"][value="Register"]').click();
    cy.url().should('not.include', 'register.htm');
  });
  it('should not register a new user with empty required fields', () => {
    cy.visit('https://parabank.parasoft.com/parabank/register.htm');
    cy.get('input[type="submit"][value="Register"]').click();
    cy.url().should('include', 'register.htm');
    cy.get('input[name="customer.firstName"]').should('be.visible');
    cy.get('input[name="customer.lastName"]').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Customer Registration Form', () => {
  test('should successfully register a new user', async ({ page }) => {
    await page.goto('https://parabank.parasoft.com/parabank/register.htm');
    await page.fill('input[name="customer.firstName"]', 'John');
    await page.fill('input[name="customer.lastName"]', 'Doe');
    await page.fill('input[name="customer.address.street"]', '123 Main St');
    await page.fill('input[name="customer.address.city"]', 'Anytown');
    await page.fill('input[name="customer.address.state"]', 'CA');
    await page.fill('input[name="customer.address.zipCode"]', '90210');
    await page.fill('input[name="customer.phoneNumber"]', '5551234567');
    await page.fill('input[name="customer.ssn"]', '123-45-6789');
    await page.fill('input[name="customer.username"]', 'johndoe');
    await page.fill('input[name="customer.password"]', 'password123');
    await page.fill('input[name="repeatedPassword"]', 'password123');
    await page.click('input[type="submit"][value="Register"]');
    await expect(page).toHaveURL(/^(?!.*register.htm).*/);
  });
  test('should not register a new user with empty required fields', async ({ page }) => {
    await page.goto('https://parabank.parasoft.com/parabank/register.htm');
    await page.click('input[type="submit"][value="Register"]');
    await expect(page).toHaveURL(/register.htm/);
    await expect(page.locator('input[name="customer.firstName"]').isVisible()).toBeTruthy();
    await expect(page.locator('input[name="customer.lastName"]').isVisible()).toBeTruthy();
  });
});
